importScripts('labor-value.js','society.js');
onmessage=event=>{const {count=12,minutes=720,seeds=[11,42,73,104]}=event.data;const cases=[{name:'Mixed village',scenario:'balanced'},{name:'Food shortage',scenario:'scarcity'},{name:'Shortage without gossip',scenario:'scarcity',gossip:false},{name:'Shortage without institutions',scenario:'scarcity',institutions:false},{name:'Shortage, all OCEAN = 50',scenario:'scarcity',traits:{O:50,C:50,E:50,A:50,N:50}}];const runs=[];try{for(const config of cases)for(const seed of seeds){const w=new Society.World({...config,count,seed});w.advance(minutes);w.validate();runs.push({case:config.name,seed,...w.metrics()});postMessage({type:'progress',done:runs.length,total:cases.length*seeds.length})}postMessage({type:'complete',result:{minutes,count,seeds,runs}})}catch(error){postMessage({type:'error',message:error.message})}};
